import {ensureSurvivalParties,partyMemberName,survivalResidentCapacity,partyMemberFree,survivalEncounterChoices} from './survival-parties.js';
const partyEsc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const partyButton=(label,action,value='',disabled=false)=>`<button data-action="${action}" data-value="${partyEsc(value)}" ${disabled?'disabled':''}>${label}</button>`;
export function survivalPartiesPage(state){
 const view=structuredClone(state);ensureSurvivalParties(view);const r=view.survivalRun,sys=r.parties,locked=!!r.activeSortie||!!r.kit?.pending||r.status!=='active',present=r.members.filter(m=>m.mind?.state!=='departed'),reserve=present.filter(m=>!sys.groups.some(p=>p.members.includes(m.key))),meeting=sys.encounters[sys.meeting],bond=sys.bonds[sys.meeting],attempt=sys.invites.find(i=>i.id===sys.meeting&&i.day===r.day),fresh=meeting?.lastMetDay===r.day;
 const meet=`<article class="party-recruit"><span class="shelter-kicker">먼저 만나고, 서로의 뜻을 확인하기</span><h2>복도에서 마주친 사람들</h2><p>말을 걸거나 도운 경험은 친밀도·신뢰·호감에 반영돼요. 초대받은 사람도 다른 약속이나 불안 때문에 거절할 수 있어요.</p>${partyButton('주변에서 사람 만나기 · 여력 1','survivalPartyMeet','',locked||r.actions<1||!survivalEncounterChoices(view).length)}${Object.values(sys.encounters).filter(e=>!r.members.some(m=>m.recruitId===e.id)&&!e.existingKey).length?`<label>다시 찾아갈 사람<select id="party-revisit">${Object.values(sys.encounters).filter(e=>!r.members.some(m=>m.recruitId===e.id)&&!e.existingKey).map(e=>`<option value="${e.id}">${partyEsc(partyMemberName(view,e))}</option>`).join('')}</select></label>${partyButton('다시 만나러 가기 · 여력 1','survivalPartyRevisit','',locked||r.actions<1)}`:''}${meeting?`<section class="party-meeting"><h3>${partyEsc(partyMemberName(view,meeting))}</h3><p>${({injured:'작은 상처를 돌보며 복도 한쪽에서 쉬고 있다.',supplies:'남은 물자를 나눠 들 방법을 찾고 있다.',waiting:meeting.waitUntil>r.day?'함께 오기로 약속한 사람을 기다리고 있다.':'기다리던 약속을 마치고 다음 동선을 고민하고 있다.'})[meeting.scene]}</p><div class="party-bonds"><span>친밀 ${bond.familiarity}</span><span>신뢰 ${bond.trust}</span><span>호감 ${bond.affection}</span>${bond.tension?`<span>불편함 ${bond.tension}</span>`:''}</div>${!fresh?'<p>다음 만남에서 다시 이야기할 수 있어요. 위에서 이 사람을 다시 찾아가세요.</p>':''}${partyButton('서로의 사정 듣기 · 여력 1','survivalPartyTalk','listen',locked||!fresh||r.actions<1||meeting.talkDay===r.day)}${partyButton('조건 없이 돕기 · 여력 1 / '+(meeting.scene==='injured'?'붕대':'생수')+' 1','survivalPartyTalk','help',locked||!fresh||r.actions<1||meeting.helpDay===r.day)}<label>함께하자고 제안할 파티<select id="party-invite-target">${sys.groups.map(p=>`<option value="${p.id}" ${p.mission||p.members.length>=6?'disabled':''}>${partyEsc(p.name)} · ${p.members.length}/6명</option>`).join('')}</select></label>${partyButton(attempt?'오늘 들은 답을 존중한다':'이 파티에서 함께할지 물어본다','survivalPartyInvite','',locked||!fresh||!!attempt||!sys.groups.some(p=>!p.mission&&p.members.length<6))}${attempt?`<p class="party-answer">“${partyEsc(attempt.reason)}”</p>`:''}</section>`:''}</article>`;
 const groups=sys.groups.map(p=>`<article class="party-group" data-party-id="${p.id}"><header><h2>${partyEsc(p.name)}</h2><strong>${p.members.length}/6명</strong></header><p>${p.members.includes('taei')?'태이가 속한 파티 · 전원이 실제 전투에 참여':p.mission?'임무 진행 중 · 배급은 출발할 때 챙겼어요. 다음 날 복귀':'다른 파티 · 별도 보급 또는 주변 경계 가능'}</p><ul>${p.members.map(k=>{const m=r.members.find(m=>m.key===k);return `<li>${partyEsc(partyMemberName(view,m))}${m?.deployment?' · 임무 중':''}</li>`;}).join('')}</ul><label>파티 이름<input id="party-name-${p.id}" value="${partyEsc(p.name)}" maxlength="24"></label>${partyButton('이름 적용','survivalPartyRename',p.id,locked||!!p.mission)}${!p.members.includes('taei')?`<label>맡길 임무<select id="party-mission-${p.id}"><option value="supply">별도 보급 · 위험에 따라 실패 가능</option><option value="guard">주변 경계 · 위협 낮추기</option></select></label><p>여력 1 · 공동 식량 ${p.members.length} / 생수 ${p.members.length} 소비. 실제 몸 상태와 주변 위협에 따라 결과가 달라져요.</p>${partyButton('임무 맡기기','survivalPartyDispatch',p.id,locked||!!p.mission||!r.base||r.actions<1)}${partyButton('해산 · 동료는 거점 대기','survivalPartyDissolve',p.id,locked||!!p.mission)}`:''}</article>`).join('');
 const roster=`<article class="party-roster"><h2>동료 편성 · 거점 전체 ${present.length}/${survivalResidentCapacity(r)}명</h2><p>한 사람은 한 파티에만 속해요. 임무 중인 파티는 복귀 후 바꿀 수 있어요. 거점이 좁으면 시설에서 추가 생활 구역을 준비하세요.</p>${present.filter(m=>m.key!=='taei').map(m=>{const owner=sys.groups.find(p=>p.members.includes(m.key));return `<div class="party-roster-row"><strong>${partyEsc(partyMemberName(view,m))}</strong><span>${partyEsc(m.partyConsent===false?'거점에서 회복 중 · 동행 미동의':owner?.name??'거점 대기')}</span>${m.partyConsent===false?partyButton('동행 이야기 나누기 · 여력 1','survivalPartyResident',m.key,locked||r.actions<1||!!m.deployment):''}<select id="party-destination-${m.key}" aria-label="${partyEsc(partyMemberName(view,m))} 편성"><option value="reserve">거점에서 대기</option>${sys.groups.map(p=>`<option value="${p.id}" ${owner?.id===p.id?'selected':''} ${p.mission||p.members.length>=6&&owner?.id!==p.id?'disabled':''}>${partyEsc(p.name)} · ${p.members.length}/6</option>`).join('')}</select>${partyButton('편성 적용','survivalPartyMove',m.key,locked||m.partyConsent===false||!!m.deployment||!partyMemberFree(r,m.key))}</div>`;}).join('')||'<p>아직 합류한 동료가 없어요. 먼저 주변에서 사람을 만나보세요.</p>'}<label>새 파티의 첫 동료<select id="party-new-member">${reserve.filter(m=>m.partyConsent!==false&&partyMemberFree(r,m.key)).map(m=>`<option value="${m.key}">${partyEsc(partyMemberName(view,m))}</option>`).join('')}</select></label><label>새 파티 이름<input id="party-new-name" value="새 보급 파티" maxlength="24"></label>${partyButton('대기 동료로 파티 만들기','survivalPartyCreate','',locked||!reserve.some(m=>m.partyConsent!==false&&partyMemberFree(r,m.key)))}</article>`;
 return `<section class="party-system"><header><span class="shelter-kicker">한 파티 1~6명 · 여러 파티 운영</span><h2>누구와, 어떻게 함께할까</h2><p>새 생존은 혼자 시작해요. 기존 저장의 동료는 그대로 유지합니다. 합류는 상대의 동의가 필요합니다. 구조한 사람은 거점에서 회복하며 대기하고, 출발 인원은 직접 편성해요.</p></header>${meet}<div class="party-groups">${groups}</div>${roster}${sys.reports.length?`<article class="party-reports"><h2>다른 파티의 복귀 보고</h2>${sys.reports.slice(-6).reverse().map(p=>`<p>사태 ${p.day}일차 · ${partyEsc(p.text)}</p>`).join('')}</article>`:''}</section>`;
}
